import Foundation
import PowerSync

/// A stored session for the local test user. Test credentials are generated by the
/// harness and kept only in the git-ignored state folder.
struct Session: Codable, Sendable {
    var email: String
    var password: String
    var userId: String
    var accessToken: String
    var expiresAt: Date
}

enum APIError: Error, CustomStringConvertible {
    /// Will never succeed if retried (bad data, constraint or permission violation).
    case permanent(status: Int, body: String)
    /// May succeed later (network down, server error, expired token).
    case transient(String)

    var description: String {
        switch self {
        case let .permanent(status, body): "permanent HTTP \(status): \(body)"
        case let .transient(message): "transient: \(message)"
        }
    }
}

/// Minimal Supabase client: Auth (password sign-in for the local test user) and
/// PostgREST (the REST API Supabase generates over Postgres; RLS applies).
struct SupabaseAPI: Sendable {
    let env: SpikeEnvironment

    // MARK: Auth

    func ensureTestUser() async throws -> Session {
        if let existing = loadSession() { return try await refreshIfNeeded(existing) }
        let email = "spike-\(UUID().uuidString.prefix(8).lowercased())@example.test"
        let password = UUID().uuidString
        _ = try await authRequest(path: "signup", body: ["email": email, "password": password])
        return try await signIn(email: email, password: password)
    }

    func currentSession() async throws -> Session {
        guard let session = loadSession() else { fail("No test user yet. Run `SyncSpike user` first.") }
        return try await refreshIfNeeded(session)
    }

    private func refreshIfNeeded(_ session: Session) async throws -> Session {
        if session.expiresAt.timeIntervalSinceNow > 120 || env.offline { return session }
        return try await signIn(email: session.email, password: session.password)
    }

    private func signIn(email: String, password: String) async throws -> Session {
        let json = try await authRequest(path: "token?grant_type=password", body: ["email": email, "password": password])
        guard let token = json["access_token"] as? String,
              let expiresIn = json["expires_in"] as? Double,
              let user = json["user"] as? [String: Any], let userId = user["id"] as? String
        else { throw APIError.transient("Unexpected sign-in response") }
        let session = Session(email: email, password: password, userId: userId, accessToken: token,
                              expiresAt: Date().addingTimeInterval(expiresIn))
        try JSONEncoder().encode(session).write(to: env.sessionFile, options: .atomic)
        return session
    }

    private func loadSession() -> Session? {
        guard let data = try? Data(contentsOf: env.sessionFile) else { return nil }
        return try? JSONDecoder().decode(Session.self, from: data)
    }

    private func authRequest(path: String, body: [String: String]) async throws -> [String: Any] {
        var request = URLRequest(url: URL(string: "\(env.supabaseURL.absoluteString)/auth/v1/\(path)")!)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.setValue(env.supabaseKey, forHTTPHeaderField: "apikey")
        request.httpBody = try JSONSerialization.data(withJSONObject: body)
        let (data, _) = try await send(request)
        return (try? JSONSerialization.jsonObject(with: data) as? [String: Any]) ?? [:]
    }

    // MARK: PostgREST

    func upsert(table: String, row: JsonParam, token: String) async throws {
        var request = restRequest(table: table, query: nil, method: "POST", token: token)
        request.setValue("resolution=merge-duplicates,return=minimal", forHTTPHeaderField: "Prefer")
        request.httpBody = try JSONEncoder().encode([row])
        _ = try await send(request)
    }

    func update(table: String, id: String, fields: JsonParam, token: String) async throws {
        var request = restRequest(table: table, query: "id=eq.\(id)", method: "PATCH", token: token)
        request.setValue("return=minimal", forHTTPHeaderField: "Prefer")
        request.httpBody = try JSONEncoder().encode(fields)
        _ = try await send(request)
    }

    func delete(table: String, id: String, token: String) async throws {
        let request = restRequest(table: table, query: "id=eq.\(id)", method: "DELETE", token: token)
        _ = try await send(request)
    }

    func select(table: String, columns: String, token: String) async throws -> [[String: Any]] {
        let request = restRequest(table: table, query: "select=\(columns)&order=id", method: "GET", token: token)
        let (data, _) = try await send(request)
        return (try JSONSerialization.jsonObject(with: data) as? [[String: Any]]) ?? []
    }

    private func restRequest(table: String, query: String?, method: String, token: String) -> URLRequest {
        let suffix = query.map { "?\($0)" } ?? ""
        var request = URLRequest(url: URL(string: "\(env.supabaseURL.absoluteString)/rest/v1/\(table)\(suffix)")!)
        request.httpMethod = method
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.setValue(env.supabaseKey, forHTTPHeaderField: "apikey")
        request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        request.timeoutInterval = 10
        return request
    }

    /// Classifies failures: 4xx data/permission errors are permanent; everything else is retryable.
    private func send(_ request: URLRequest) async throws -> (Data, HTTPURLResponse) {
        let data: Data
        let response: URLResponse
        do {
            (data, response) = try await URLSession.shared.data(for: request)
        } catch {
            throw APIError.transient("network: \(error.localizedDescription)")
        }
        guard let http = response as? HTTPURLResponse else { throw APIError.transient("no HTTP response") }
        let body = String(data: data, encoding: .utf8) ?? ""
        switch http.statusCode {
        case 200 ..< 300: return (data, http)
        case 401, 408, 429: throw APIError.transient("HTTP \(http.statusCode): \(body)")
        case 400 ..< 500: throw APIError.permanent(status: http.statusCode, body: body)
        default: throw APIError.transient("HTTP \(http.statusCode): \(body)")
        }
    }
}
